-- Register an official IR/news source for every remaining ontology company.
-- URLs were discovered from company-controlled IR, newsroom, or RSS pages.
-- SEC filing coverage remains the fallback for every company.

insert into public.market_issue_sources (
  env,
  source_type,
  source_key,
  account_handle,
  display_name,
  source_class,
  source_tags,
  active,
  allow_single_source_publish,
  adapter_type,
  channel_type,
  discovery_url,
  canonical_host,
  poll_interval_seconds,
  priority,
  max_items_per_poll,
  adapter_config
)
select
  'prod',
  'web',
  'official-ir-' || lower(row.ticker),
  null,
  row.display_name,
  'company_official',
  array['official', 'company_news']::text[],
  true,
  false,
  row.adapter_type,
  'company_news',
  row.discovery_url,
  row.canonical_host,
  row.poll_interval_seconds,
  50,
  20,
  jsonb_build_object(
    'company_tickers', jsonb_build_array(row.ticker),
    'official_source', true,
    'discovery_method', 'web_search',
    'include_path_regex', '(news|press|release|investor|financial|earnings|reports|media|events)',
    'exclude_path_regex', '(contact|careers|privacy|legal|login|sitemap)'
  )
